import { useSyncExternalStore } from 'react';
import { fetchAllAssets } from '../api/assets';
import { approvalsSummary } from '../api/misc';
import { listFormRequests } from '../api/forms';
import type { Asset, User } from '../types';

// In-app notifications — port of the legacy dashboard/js/notifications.js.
// Same per-user localStorage keys, so read/cleared state is shared with the
// legacy pages. Alerts are generated by periodically scanning the registry.

export interface AppNotification {
  id: string;
  type: string;
  title: string;
  body: string;
  assetId: string | null;     // also the per-item dedup key (legacy behaviour)
  icon: string;
  color: string;
  ts: number;
}

const uid = () => { try { const u = JSON.parse(localStorage.getItem('as_user') || '{}'); return u._id || u.id || 'guest'; } catch { return 'guest'; } };
const keys = () => ({ list: `as_notifications_${uid()}`, read: `as_notif_read_${uid()}`, cleared: `as_notif_cleared_${uid()}` });
function readJson<T>(key: string, fallback: T): T { try { return JSON.parse(localStorage.getItem(key) || 'null') ?? fallback; } catch { return fallback; } }
function writeJson(key: string, v: unknown) { try { localStorage.setItem(key, JSON.stringify(v)); } catch { /* storage full/blocked */ } }

// ── Store with change notification for React ─────────────────────────────────
const listeners = new Set<() => void>();
let snapshot = load();
function load() {
  const k = keys();
  const list = readJson<AppNotification[]>(k.list, []);
  const read = new Set(readJson<string[]>(k.read, []));
  return { list, read, unread: list.filter(n => !read.has(n.id)).length };
}
function changed() { snapshot = load(); listeners.forEach(l => l()); }
if (typeof window !== 'undefined') {
  window.addEventListener('storage', e => { if (e.key?.startsWith('as_notif')) changed(); });
}

export function useNotifications() {
  return useSyncExternalStore(cb => { listeners.add(cb); return () => listeners.delete(cb); }, () => snapshot);
}
/** Re-read storage (e.g. after the signed-in user changes). */
export const refreshNotifications = changed;

export function markRead(id: string) {
  const k = keys();
  const read = new Set(readJson<string[]>(k.read, []));
  read.add(id);
  writeJson(k.read, [...read]);
  changed();
}
export function markAllRead() {
  const k = keys();
  writeJson(k.read, readJson<AppNotification[]>(k.list, []).map(n => n.id));
  changed();
}
/** Clear everything; cleared alerts aren't re-raised by later scans. */
export function clearAll() {
  const k = keys();
  const cleared = new Set(readJson<string[]>(k.cleared, []));
  readJson<AppNotification[]>(k.list, []).forEach(n => cleared.add(`${n.type}|${n.assetId || ''}`));
  writeJson(k.cleared, [...cleared]);
  writeJson(k.list, []);
  try { localStorage.removeItem(k.read); } catch { /* ignore */ }
  changed();
}

/**
 * Add a notification, or update the same type (+assetId) from the last 24h in
 * place — a re-scan that finds "14 assets" became "12" edits one entry and
 * marks it unread again instead of adding a duplicate.
 */
export function pushNotification(n: Omit<AppNotification, 'id' | 'ts'>) {
  const k = keys();
  const assetId = n.assetId || null;
  if (new Set(readJson<string[]>(k.cleared, [])).has(`${n.type}|${assetId || ''}`)) return;
  const list = readJson<AppNotification[]>(k.list, []);
  const i = list.findIndex(x => x.type === n.type && x.assetId === assetId && x.ts > Date.now() - 86400000);
  if (i !== -1) {
    if (list[i].body === n.body) return;
    list[i] = { ...list[i], title: n.title, body: n.body, ts: Date.now() };
    const read = new Set(readJson<string[]>(k.read, []));
    read.delete(list[i].id);
    writeJson(k.read, [...read]);
  } else {
    list.unshift({ ...n, assetId, id: `N-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`, ts: Date.now() });
  }
  writeJson(k.list, list.slice(0, 200));
  changed();
}

/** Where clicking a notification goes. */
export function notificationLink(n: AppNotification, role?: string): string | null {
  if (n.type === 'MY_FORM_DECIDED') return role === 'MDA Agent' ? '/portal' : '/form-requests';
  if (n.assetId) return `/assets/${encodeURIComponent(n.assetId)}`;
  return ({
    INSPECTION_OVERDUE: '/inspections', INSPECTION_DUE: '/inspections', PENDING_APPROVALS: '/approvals',
    CRITICAL_CONDITION: '/assets?condition=Critical', MISSING_COORDS: '/assets',
  } as Record<string, string>)[n.type] || null;
}

// ── Alert scan (role-filtered) ───────────────────────────────────────────────
const ROLE_FILTER: Record<string, string[]> = {
  INSPECTION_OVERDUE: ['System Admin', 'Supervisor', 'Sub-Head'],
  INSPECTION_DUE:     ['System Admin', 'Supervisor', 'Sub-Head', 'GIS Analyst'],
  CRITICAL_CONDITION: ['System Admin', 'Supervisor', 'Sub-Head', 'GIS Analyst', 'Field Agent'],
  MISSING_COORDS:     ['System Admin', 'GIS Analyst', 'Field Agent'],
  PENDING_APPROVALS:  ['System Admin', 'Supervisor', 'Sub-Head'],
};
const canSee = (type: string, role: string) => !ROLE_FILTER[type] || ROLE_FILTER[type].includes(role);
const refId = (r: unknown) => (r && typeof r === 'object' ? (r as { _id?: string })._id : r) as string | undefined;
const RECENT_MS = 3 * 86400000;

export async function runAlertScan(user: User) {
  const role = user.role;
  const now = Date.now();
  const isAgent = role === 'MDA Agent';

  if (!isAgent) {
    const list = await fetchAllAssets().catch((): Asset[] => []);
    const soon = now + 7 * 86400000;
    const buckets: Record<string, typeof list> = { INSPECTION_OVERDUE: [], INSPECTION_DUE: [], CRITICAL_CONDITION: [], MISSING_COORDS: [] };
    list.forEach(a => {
      const next = a.nextInspection ? new Date(a.nextInspection).getTime() : NaN;
      if (next < now) buckets.INSPECTION_OVERDUE.push(a);
      else if (next <= soon) buckets.INSPECTION_DUE.push(a);
      if (a.condition === 'Critical') buckets.CRITICAL_CONDITION.push(a);
      if (!a.lat && !a.location?.coordinates?.[1]) buckets.MISSING_COORDS.push(a);
    });
    const DEFS: Record<string, { title: string; icon: string; color: string; one: (name: string, a: (typeof list)[0]) => string; many: (n: number) => string }> = {
      INSPECTION_OVERDUE: { title: 'Inspections overdue', icon: 'fa-calendar-xmark', color: '#e05555', one: n => `${n} is overdue for inspection`, many: n => `${n} assets are overdue for inspection` },
      INSPECTION_DUE: { title: 'Inspections due soon', icon: 'fa-calendar-day', color: '#f0a500', one: (n, a) => `${n} inspection due ${(a.nextInspection || '').slice(0, 10)}`, many: n => `${n} assets have inspections due within 7 days` },
      CRITICAL_CONDITION: { title: 'Critical assets', icon: 'fa-triangle-exclamation', color: '#e05555', one: n => `${n} is in Critical condition — immediate attention required`, many: n => `${n} assets are in Critical condition — review needed` },
      MISSING_COORDS: { title: 'Missing GPS coordinates', icon: 'fa-location-crosshairs', color: '#5A6A7A', one: n => `${n} has no coordinates — capture GPS to place it on the map`, many: n => `${n} assets have no coordinates — capture GPS to place them on the map` },
    };
    Object.entries(buckets).forEach(([type, matches]) => {
      if (!matches.length || !canSee(type, role)) return;
      const d = DEFS[type], first = matches[0];
      pushNotification({
        type, title: d.title, icon: d.icon, color: d.color,
        assetId: matches.length === 1 ? first.assetId || null : null,
        body: matches.length === 1 ? d.one(first.name || first.assetId || 'An asset', first) : d.many(matches.length),
      });
    });

    if (canSee('PENDING_APPROVALS', role)) {
      const s = await approvalsSummary().catch(() => null);
      if (s && s.pending > 0) pushNotification({ type: 'PENDING_APPROVALS', assetId: null, title: 'Pending approvals', body: `${s.pending} asset capture${s.pending === 1 ? '' : 's'} awaiting your review`, icon: 'fa-stamp', color: '#f0a500' });
    }

    // Decisions on the user's own captures in the last 3 days.
    list.filter(a => refId(a.capturedBy) === user._id && (a.approvalStatus === 'Approved' || a.approvalStatus === 'Rejected') && a.reviewedAt && now - new Date(a.reviewedAt).getTime() < RECENT_MS)
      .forEach(a => {
        const ok = a.approvalStatus === 'Approved';
        pushNotification({ type: 'MY_ASSET_DECIDED', assetId: a.assetId || null, title: ok ? 'Capture approved' : 'Capture rejected',
          body: `${a.name || a.assetId} was ${ok ? 'approved' : 'rejected'}${a.rejectionReason ? ` — ${a.rejectionReason}` : ''}`,
          icon: ok ? 'fa-circle-check' : 'fa-circle-xmark', color: ok ? '#2DB87B' : '#e05555' });
      });
  }

  // Decisions on the user's own form requests in the last 3 days (MDA Agents mostly).
  const forms = await listFormRequests().catch(() => []);
  forms.filter(r => refId(r.submittedBy) === user._id && (r.status === 'Approved' || r.status === 'Rejected') && r.reviewedAt && now - new Date(r.reviewedAt).getTime() < RECENT_MS)
    .forEach(r => {
      const ok = r.status === 'Approved';
      pushNotification({ type: 'MY_FORM_DECIDED', assetId: r._id, title: ok ? 'Form request approved' : 'Form request rejected',
        body: `${String(r.formType).replace(/_/g, ' ').toLowerCase()} was ${ok ? 'approved' : 'rejected'}${r.reviewRemarks ? ` — ${r.reviewRemarks}` : ''}`,
        icon: ok ? 'fa-circle-check' : 'fa-circle-xmark', color: ok ? '#2DB87B' : '#e05555' });
    });
}
